# Adds the XCUITest target to the Expo-generated iOS project (ios/ is regenerated by "expo prebuild", so the target is added by this
# script, never committed). Idempotent. Run from apps/tech-native after prebuild: ruby xcuitest/add-uitests.rb
# Uses the xcodeproj gem that ships with CocoaPods. The simulator build is signed ad hoc ("Sign to Run Locally"): no team, no
# account, no profile (signing with the owner's account is P6-TESTFLIGHT's).
require 'fileutils'
require 'xcodeproj'

TARGET = 'RightOnTimeUITests'
# Every suite file in this folder (ShellUITests, MapMeUITests, ...); run.sh picks the classes to run.
SOURCES = Dir[File.join(__dir__, '*UITests.swift')].map { |f| File.basename(f) }.sort.freeze
ROOT = File.expand_path('..', __dir__)
ios = File.join(ROOT, 'ios')
proj_path = Dir[File.join(ios, '*.xcodeproj')].first or abort('add-uitests: no ios/*.xcodeproj; run expo prebuild first')
project = Xcodeproj::Project.open(proj_path)
app = project.native_targets.find { |t| t.product_type == 'com.apple.product-type.application' } or abort('add-uitests: no app target')

if project.native_targets.any? { |t| t.name == TARGET }
  puts "add-uitests: #{TARGET} already present"
  exit 0
end

src_dir = File.join(ios, TARGET)
FileUtils.mkdir_p(src_dir)
SOURCES.each { |f| FileUtils.cp(File.join(__dir__, f), src_dir) }

deployment = app.build_configurations.first.build_settings['IPHONEOS_DEPLOYMENT_TARGET'] || '16.4'
target = project.new_target(:ui_test_bundle, TARGET, :ios, deployment, nil, :swift)
group = project.main_group.new_group(TARGET, TARGET)
target.add_file_references(SOURCES.map { |f| group.new_reference(f) })
target.add_dependency(app)

bundle_id = app.build_configurations.first.build_settings['PRODUCT_BUNDLE_IDENTIFIER']
unsigned = { 'DEVELOPMENT_TEAM' => '', 'CODE_SIGN_STYLE' => 'Manual', 'CODE_SIGN_IDENTITY' => '-', 'PROVISIONING_PROFILE_SPECIFIER' => '' }
target.build_configurations.each do |c|
  s = c.build_settings
  s['PRODUCT_NAME'] = '$(TARGET_NAME)'
  s['PRODUCT_BUNDLE_IDENTIFIER'] = "#{bundle_id}.uitests"
  s['TEST_TARGET_NAME'] = app.name
  s['GENERATE_INFOPLIST_FILE'] = 'YES'
  s['SWIFT_VERSION'] = '5.0'
  s['TARGETED_DEVICE_FAMILY'] = '1'
  s.merge!(unsigned)
end
# F-988: the TestFlight project (prebuild.sh --release, BW_RELEASE=1) keeps the app target's own signing (automatic, the team from app.json), which
# the archive needs; the rig's project builds the app unsigned for the simulator.
app.build_configurations.each { |c| c.build_settings.merge!(unsigned) } unless ENV['BW_RELEASE'] == '1'

# Attach the UI tests to the app's shared scheme so "xcodebuild test -scheme <app>" runs them, on the Release build: the JS bundle is
# embedded, so no Metro server runs during the suite.
scheme_path = File.join(proj_path, 'xcshareddata', 'xcschemes', "#{app.name}.xcscheme")
scheme = File.exist?(scheme_path) ? Xcodeproj::XCScheme.new(scheme_path) : Xcodeproj::XCScheme.new
scheme.add_build_target(app) unless File.exist?(scheme_path)
scheme.add_test_target(target)
scheme.test_action.build_configuration = 'Release'
scheme.launch_action.build_configuration = 'Release'
project.save
scheme.save_as(proj_path, app.name, true)
puts "add-uitests: added #{TARGET} (#{bundle_id}.uitests) to #{File.basename(proj_path)}, ad hoc signed"
